window.CompanionWorkspaceBundle["life"]="<!doctype html>\n<html lang=\"zh-CN\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>日记与生活 · 陪伴</title>\n  <style>:root {\n  color-scheme: light;\n  --page: #f5f5fa; --surface: #fff; --surface-muted: #fafaff; --ink: #3b3e52; --muted: #6c7086; --ink-soft: #9a9db5;\n  --line: #ececf4; --line-strong: #e0e0ec; --accent: #4f53a8; --accent-strong: #6c73bb; --accent-soft: #eceefb;\n  --success: #3f8a68; --success-soft: #e8f4ee; --warning: #a97b1c; --warning-soft: #fdf3e0; --danger: #a94f4a; --danger-soft: #fbeceb;\n  --shadow: 0 1px 2px rgba(59,62,82,.04), 0 8px 24px rgba(59,62,82,.06); --backdrop: rgba(25,27,45,.48);\n  font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", \"Microsoft YaHei\", sans-serif; color: var(--ink); background: var(--page); line-height: 1.65; font-size: 14px;\n}\n:root[data-theme=\"night\"] { color-scheme: dark; --page:#14151e; --surface:#1c1e29; --surface-muted:#212332; --ink:#e6e7f0; --muted:#a9acc2; --ink-soft:#7e8298; --line:#2a2d3c; --line-strong:#343850; --accent:#a5abf2; --accent-strong:#8b91e0; --accent-soft:#272a45; --success:#6cc39c; --success-soft:rgba(108,195,156,.14); --warning:#e6bd63; --warning-soft:rgba(230,189,99,.14); --danger:#e88b85; --danger-soft:rgba(232,139,133,.14); --shadow:0 1px 2px rgba(0,0,0,.3),0 10px 28px rgba(0,0,0,.28); --backdrop:rgba(0,0,0,.58); }\n:root[data-theme=\"grove\"] { --page:#f3f7f3; --surface:#fff; --surface-muted:#f8fbf7; --ink:#293a32; --muted:#61736a; --ink-soft:#8b9a90; --line:#dfe8e0; --line-strong:#cfdccf; --accent:#39734f; --accent-strong:#4c8b63; --accent-soft:#e8f1e8; --success:#39734f; --success-soft:#e5f1e7; --warning:#9a6b25; --warning-soft:#f8f0df; --danger:#a34c43; --danger-soft:#f8eae7; --shadow:0 1px 2px rgba(41,58,50,.04),0 8px 24px rgba(41,58,50,.06); --backdrop:rgba(23,44,36,.56); }\n:root[data-theme=\"coral\"] { --page:#fbf4f1; --surface:#fff; --surface-muted:#fff9f6; --ink:#443633; --muted:#796760; --ink-soft:#a18e86; --line:#efe1db; --line-strong:#e2cfc6; --accent:#b65d4c; --accent-strong:#c87561; --accent-soft:#fae9e1; --success:#4d8068; --success-soft:#eaf2ec; --warning:#9c7025; --warning-soft:#fbf0df; --danger:#a94f4a; --danger-soft:#fbeceb; --shadow:0 1px 2px rgba(68,54,51,.04),0 8px 24px rgba(68,54,51,.06); --backdrop:rgba(68,35,31,.46); }\n* { box-sizing: border-box; } body { margin: 0; background: var(--page); color: var(--ink); } [hidden] { display: none !important; }\nmain { max-width: 1260px; padding: 32px; margin: auto; } h1,h2,h3,p { margin: 0; } h1 { font-size: 30px; font-weight: 650; margin: 6px 0; } h2 { font-size: 19px; } h3 { font-size: 16px; }\n.eyebrow { font-size: 12px; letter-spacing: .08em; color: var(--accent); } .eyebrow span { margin: 0 12px; color: var(--ink-soft); } .muted { color: var(--muted); font-size: 13px; }\nheader,.section-head { display: flex; justify-content: space-between; align-items: center; gap: 20px; } header { margin-bottom: 26px; } .host-controls { display: flex; flex-wrap: wrap; justify-content: flex-end; gap: 8px; }\nbutton,input,textarea,select { font: inherit; } button { min-height: 42px; padding: 8px 16px; border-radius: 6px; border: 1px solid transparent; cursor: pointer; flex-shrink: 0; } button:hover:not(:disabled) { filter: brightness(.95); } button:disabled { opacity: .48; cursor: default; } :focus-visible { outline: 3px solid var(--accent-strong); outline-offset: 3px; }\n.primary { background: var(--accent); color: #fff; } .secondary { background: var(--surface); border-color: var(--line-strong); color: var(--ink); } .quiet { background: transparent; color: var(--accent); } .danger { background: var(--surface); border-color: color-mix(in srgb,var(--danger) 42%,var(--line)); color: var(--danger); }\n.scope { display: grid; grid-template-columns: repeat(4,minmax(0,1fr)); border-block: 1px solid var(--line-strong); padding: 18px 0; gap: 22px; } .scope span { display: block; color: var(--muted); font-size: 12px; } .scope strong { display: block; overflow-wrap: anywhere; font-weight: 600; }\n.schedule-hint { margin-top: 10px; } .sleep-plan { display: grid; grid-template-columns: repeat(4,minmax(0,1fr)); gap: 16px; padding: 16px 0; border-bottom: 1px solid var(--line-strong); } .sleep-plan span { display: block; color: var(--muted); font-size: 12px; } .sleep-plan strong { display: block; overflow-wrap: anywhere; font-weight: 600; }\n.sleep-physiology { display: grid; grid-template-columns: repeat(4,minmax(0,1fr)); gap: 16px; padding: 14px 0 18px; border-bottom: 1px solid var(--line-strong); } .sleep-physiology span { display: block; color: var(--muted); font-size: 12px; } .sleep-physiology strong { display: block; overflow-wrap: anywhere; font-weight: 600; }\n#notice { margin: 18px 0; padding: 12px 16px; border-radius: 6px; background: var(--success-soft); color: var(--success); } #notice.error,#dialog-error { background: var(--danger-soft); color: var(--danger); padding: 12px; border-radius: 6px; }\ndetails { margin: 22px 0; background: var(--surface); border: 1px solid var(--line); border-radius: 8px; box-shadow: var(--shadow); } summary { padding: 17px 20px; cursor: pointer; font-weight: 600; } summary span { margin-left: 16px; color: var(--muted); font-size: 12px; font-weight: 400; }\n#config-form { padding: 0 22px 22px; } .config-grid { display: grid; grid-template-columns: repeat(3,minmax(0,1fr)); gap: 18px 26px; } label { display: block; font-size: 13px; color: var(--muted); margin: 12px 0; }\ninput:not([type=checkbox]),textarea,select { width: 100%; display: block; margin-top: 6px; min-height: 42px; padding: 9px 12px; color: var(--ink); background: var(--surface); border: 1px solid var(--line-strong); border-radius: 5px; } textarea { resize: vertical; line-height: 1.85; } input[type=checkbox] { width: 18px; height: 18px; accent-color: var(--accent); }\nlabel.check { display: flex; align-items: center; gap: 10px; } .form-footer { display: flex; gap: 20px; align-items: center; justify-content: space-between; margin-top: 18px; }\n.tabs { display: flex; gap: 12px; border-bottom: 1px solid var(--line); margin-bottom: 24px; overflow-x: auto; } .tabs button { color: var(--muted); background: transparent; border-radius: 0; border-bottom: 3px solid transparent; } .tabs button[aria-current=page] { color: var(--accent); border-bottom-color: var(--accent-strong); font-weight: 600; }\n.section-head { margin-bottom: 20px; } .section-head p { margin-top: 4px; } .archive-layout { display: grid; grid-template-columns: 290px minmax(0,1fr); border: 1px solid var(--line); background: var(--surface); border-radius: 8px; min-height: 420px; overflow: hidden; box-shadow: var(--shadow); }\naside { border-right: 1px solid var(--line); } .journal-link { display: block; text-align: left; width: 100%; color: var(--ink); background: var(--surface); border-radius: 0; border-bottom: 1px solid var(--line); border-left: 3px solid transparent; padding: 18px; white-space: normal; } .journal-link[aria-current=true] { background: var(--accent-soft); border-left-color: var(--accent-strong); } .journal-link small { display: block; color: var(--muted); margin-top: 4px; }\n#journal-detail { padding: 30px; min-width: 0; } .prose { white-space: pre-wrap; overflow-wrap: anywhere; line-height: 2; font-size: 15px; margin-top: 22px; } .afterglow { border-left: 2px solid var(--accent-strong); padding-left: 16px; margin-top: 20px; white-space: pre-wrap; } .journal-summary { background: var(--surface-muted); padding: 16px; margin-top: 24px; border-radius: 6px; }\n.actions { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 20px; } .badge { color: var(--success); background: var(--success-soft); padding: 2px 9px; border-radius: 4px; font-size: 12px; } .activity { padding: 22px; border: 1px solid var(--line); border-radius: 8px; background: var(--surface); margin-bottom: 14px; min-width: 0; overflow-wrap: anywhere; box-shadow: var(--shadow); }\n.activity h3 { margin-bottom: 6px; } .activity .prose { font-size: 14px; } .activity .code { font-size: 11px; color: var(--ink-soft); margin-top: 8px; } .pagination { display: flex; justify-content: space-between; gap: 10px; padding: 14px; } .empty { padding: 34px 20px; color: var(--muted); text-align: center; } .retry-form { max-width: 640px; padding: 22px; border: 1px solid var(--line); border-radius: 8px; background: var(--surface); box-shadow: var(--shadow); }\ndialog { width: min(680px,calc(100% - 28px)); max-height: 90dvh; padding: 28px; border: 1px solid var(--line-strong); border-radius: 10px; color: var(--ink); background: var(--surface); overflow-y: auto; box-shadow: 0 22px 80px var(--shadow); } dialog::backdrop { background: var(--backdrop); } .dialog-actions { display: flex; justify-content: flex-end; margin-top: 22px; }\n@media (max-width:760px) { main { padding: 22px 16px; } h1 { font-size: 25px; } .scope { grid-template-columns: repeat(2,minmax(0,1fr)); gap: 14px; } .sleep-plan,.sleep-physiology { grid-template-columns: repeat(2,minmax(0,1fr)); gap: 12px; } .config-grid { grid-template-columns: repeat(2,minmax(0,1fr)); } .archive-layout { grid-template-columns: 1fr; } aside { border-right: 0; border-bottom: 1px solid var(--line); } #journal-list { max-height: 220px; overflow-y: auto; } #journal-detail { padding: 22px; } summary span { display: block; margin: 6px 0 0 16px; } .tabs { gap: 0; } .tabs button { padding: 10px 12px; } .section-head { align-items: flex-start; } .form-footer { flex-wrap: wrap; } }\n@media (max-width:430px) { .config-grid { grid-template-columns: 1fr; gap: 0; } header { align-items: flex-start; } .section-head { flex-wrap: wrap; } .activity { padding: 18px; } dialog { padding: 20px; } .tabs button { padding: 10px; } }\n@media (prefers-reduced-motion:reduce) { *,*::before,*::after { scroll-behavior: auto !important; transition: none !important; } }\n/* === 显示维度 ===\n   由 embedded-bridge.js 写入 <html data-*>，与主页面同名同值。\n   工作区在 srcdoc 中加载，没有 base URL，所以这里必须是本文件的一部分，\n   不能拆成外部 <link>；主题色板见本文件上方的 :root[data-theme=...]。 */\n:root { --r-sm: 8px; --r-lg: 8px; --gap: 22px; --pad: 32px; --type-scale: 1; }\n:root[data-radius=\"sharp\"] { --r-sm: 4px; --r-lg: 5px; }\n:root[data-radius=\"round\"] { --r-sm: 14px; --r-lg: 20px; }\n:root[data-density=\"compact\"] { --gap: 14px; --pad: 22px; }\n:root[data-density=\"roomy\"] { --gap: 30px; --pad: 42px; }\n:root[data-type-scale=\"s\"] { --type-scale: .94; }\n:root[data-type-scale=\"l\"] { --type-scale: 1.08; }\n:root[data-type-scale=\"xl\"] { --type-scale: 1.18; }\n:root[data-type-scale] body { font-size: calc(14px * var(--type-scale)); }\n:root[data-radius] :is(details,.archive-layout,.activity,.retry-form,dialog,#notice,.journal-summary) { border-radius: var(--r-lg); }\n:root[data-radius] :is(button,input:not([type=checkbox]),textarea,select) { border-radius: var(--r-sm); }\n:root[data-density] main { padding: var(--pad); }\n:root[data-density] .scope { gap: var(--gap); padding: 14px 0; }\n:root[data-density] .sleep-plan { gap: var(--gap); padding: 13px 0; }\n:root[data-density] .sleep-physiology { gap: var(--gap); padding: 13px 0; }\n:root[data-density] .config-grid { gap: 14px var(--gap); }\n:root[data-density] :is(.activity,.retry-form) { padding: var(--pad); margin-bottom: 12px; }\n:root[data-motion=\"low\"] *, :root[data-motion=\"low\"] *::before, :root[data-motion=\"low\"] *::after { transition-duration: .06s !important; }\n:root[data-motion=\"off\"] *, :root[data-motion=\"off\"] *::before, :root[data-motion=\"off\"] *::after {\n  animation: none !important; transition: none !important; scroll-behavior: auto !important;\n}\n\n/* === 动效与质感层 ===\n   与「关系与权限」工作区同一套语言：入场浮现、列表 stagger、悬停微位移、\n   加载 shimmer 与对话浮现。全部尊重上方的 data-motion 维度与 reduced-motion。 */\n@keyframes rise { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: none; } }\n@keyframes fade { from { opacity: 0; } to { opacity: 1; } }\n@keyframes shimmer { from { background-position: 200% 0; } to { background-position: -200% 0; } }\n@keyframes float { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-4px); } }\n\nmain > * { animation: rise .4s both; }\nmain > *:nth-child(2) { animation-delay: .05s; }\nmain > *:nth-child(3) { animation-delay: .09s; }\nmain > *:nth-child(n+4) { animation-delay: .12s; }\n#notice { animation: rise .35s both; }\n.journal-link { transition: background .25s, border-color .25s, transform .25s; }\n.journal-link:hover { background: var(--surface-muted); border-left-color: var(--accent); transform: translateX(2px); }\n#journal-list .journal-link { animation: rise .4s both; }\n#journal-list .journal-link:nth-child(1) { animation-delay: .02s; }\n#journal-list .journal-link:nth-child(2) { animation-delay: .05s; }\n#journal-list .journal-link:nth-child(3) { animation-delay: .08s; }\n#journal-list .journal-link:nth-child(4) { animation-delay: .11s; }\n#journal-list .journal-link:nth-child(n+5) { animation-delay: .14s; }\n.activity, .retry-form { transition: transform .3s cubic-bezier(.2,.8,.2,1), box-shadow .3s, border-color .3s; }\n.activity:hover, .retry-form:hover { transform: translateY(-2px); box-shadow: 0 2px 4px rgba(59,62,82,.06), 0 12px 30px rgba(79,83,168,.12); border-color: var(--line-strong); }\n.activity { animation: rise .45s both; }\n.activity:nth-child(2) { animation-delay: .05s; }\n.activity:nth-child(3) { animation-delay: .1s; }\n.activity:nth-child(n+4) { animation-delay: .14s; }\ndetails[open] #config-form { animation: rise .35s both; }\n.tabs button { transition: color .25s, background .25s, border-color .25s; }\n.tabs button:hover { background: var(--surface-muted); }\ndialog[open] { animation: rise .3s both; }\ndialog::backdrop { animation: fade .3s both; }\n@media (prefers-reduced-motion:reduce) { *,*::before,*::after { animation: none !important; } }\n:root[data-motion=\"low\"] *, :root[data-motion=\"low\"] *::before, :root[data-motion=\"low\"] *::after { animation-duration: .06s !important; }\n\n/* 陪伴小屋语义令牌层\n   单一变量源：主题、密度、圆角、字号、动效全部在此声明。\n\n   色板取向：界面色取自体素小屋本身的材料——木作、草地、黄昏、夜色——\n   而不是从通用仪表盘继承的冷紫。这样界面看起来像屋子的一部分，\n   而不是叠在屋子上面的一块玻璃。\n\n   每套主题必须声明全部 --t-* 变量。令牌被组件直接引用，\n   漏掉一个不会回落成默认值，而是变成无效值（继承失败即透明/黑）。\n   完整性由 tools/audit_theme_tokens.py 校验。 */\n\n/* === 主题色板 ===\n   六套，按明暗分组，每套对应小屋的一个时段或一种陈设风格。\n   :root 不带 data-theme 时用庭院兜底，避免令牌为空。\n\n   每个色板写两条选择器：一条 :root[data-theme=...]（整站生效），\n   一条 [data-theme=...]（同块作用域）。后者是给主题色卡用的——\n   色卡预览元素带上 data-theme 就能取到那套主题的真实色值，\n   于是「色卡里画出来的」就是「选中后真实的」，不需要另抄一份色值。\n   两条选择器必须成对出现，audit_theme_tokens.py 会核对两边的令牌集合一致。 */\n:root,\n:root[data-theme=\"dawn\"],\n[data-theme=\"dawn\"],\n:root[data-theme=\"light\"]{\n  /* 晨雾 · 清晨的浅暖米白，木色点缀 */\n  --t-canvas:#f4f1ea;\n  --t-surface:#fffdf8;\n  --t-surface-soft:#f9f6ef;\n  --t-surface-raised:#ffffff;\n  --t-surface-sunken:#ece7dc;\n  --t-veil:rgba(255,253,248,.72);\n  --t-text:#3b3730;\n  --t-text-strong:#282520;\n  --t-text-soft:#6d675b;\n  /* 弱化文字要能读：原 #8c857a 对画布只有 3.24:1，正文级字号不达 4.5:1。 */\n  --t-text-faint:#726d65;\n  --t-text-invert:#fffdf8;\n  --t-accent:#9a6f45;\n  --t-accent-hover:#7d5936;\n  --t-accent-quiet:#f2e8d9;\n  --t-accent-ink:#7a5636;\n  --t-accent-solid:#8a6540;\n  --t-accent-solid-hover:#725235;\n  --t-on-solid:#fffdf8;\n  --t-line:rgba(120,105,85,.16);\n  --t-line-firm:rgba(120,105,85,.28);\n  --t-ok:#5f7f52;\n  --t-ok-quiet:#eaf0e3;\n  --t-ok-ink:#4e6a43;\n  --t-warn:#a8802f;\n  --t-warn-quiet:#f8efda;\n  --t-warn-ink:#87661f;\n  --t-risk:#a86055;\n  --t-risk-quiet:#f7e9e5;\n  --t-risk-ink:#8a4c43;\n  /* 焦点环必须是实色。带 alpha 的环合成到背景后只有 1.3–2.2:1，\n     WCAG 1.4.11 要求指示器 ≥3:1；六套主题一律改成不透明强调色。 */\n  --t-focus:#896540;\n  --t-shadow:0 8px 28px rgba(96,80,60,.07);\n  --t-shadow-lift:0 14px 36px rgba(96,80,60,.13);\n  --t-brand:#a87d52;\n  /* 场景联动：界面用晨光时，小屋也走清晨光照 */\n  --t-scene-light:dawn;\n  --skin-heading-font:\"Noto Serif SC\",\"Songti SC\",\"SimSun\",serif;\n  --skin-canvas-pattern:linear-gradient(90deg,color-mix(in srgb,var(--t-accent) 8%,transparent) 1px,transparent 1px),\n    repeating-linear-gradient(0deg,transparent 0 31px,color-mix(in srgb,var(--t-accent) 5%,transparent) 31px 32px);\n  --skin-canvas-size:40px 100%,auto;\n  --skin-r-2xs:2px;--skin-r-xs:5px;--skin-r-sm:8px;--skin-r-md:11px;--skin-r-lg:15px;--skin-r-xl:20px;\n}\n\n\n:root[data-theme=\"courtyard\"],\n[data-theme=\"courtyard\"]{\n  /* 庭院 · 日间的清爽草绿与天光，是默认主题 */\n  --t-canvas:#eef3ec;\n  --t-surface:#fdfefb;\n  --t-surface-soft:#f5f9f3;\n  --t-surface-raised:#ffffff;\n  --t-surface-sunken:#e3ebe0;\n  --t-veil:rgba(253,254,251,.72);\n  --t-text:#333a33;\n  --t-text-strong:#212822;\n  --t-text-soft:#616b60;\n  --t-text-faint:#687068;\n  --t-text-invert:#fdfefb;\n  --t-accent:#4a7c50;\n  --t-accent-hover:#3a6540;\n  --t-accent-quiet:#e6efe4;\n  --t-accent-ink:#3b6541;\n  --t-accent-solid:#46754c;\n  --t-accent-solid-hover:#375e3d;\n  --t-on-solid:#fdfefb;\n  --t-line:rgba(74,90,74,.14);\n  --t-line-firm:rgba(74,90,74,.26);\n  --t-ok:#4a7c50;\n  --t-ok-quiet:#e4efe2;\n  --t-ok-ink:#3b6541;\n  --t-warn:#9c7422;\n  --t-warn-quiet:#f7f0dc;\n  --t-warn-ink:#7d5c17;\n  --t-risk:#a5524a;\n  --t-risk-quiet:#f7e9e6;\n  --t-risk-ink:#874139;\n  --t-focus:#46754c;\n  --t-shadow:0 8px 28px rgba(58,80,60,.06);\n  --t-shadow-lift:0 14px 36px rgba(58,80,60,.12);\n  --t-brand:#57875d;\n  --t-scene-light:day;\n  --skin-heading-font:\"MiSans\",\"Microsoft YaHei\",\"PingFang SC\",system-ui,sans-serif;\n  --skin-canvas-pattern:linear-gradient(90deg,transparent 0 63px,color-mix(in srgb,var(--t-accent) 5%,transparent) 63px 64px);\n  --skin-canvas-size:auto;\n  --skin-r-2xs:3px;--skin-r-xs:7px;--skin-r-sm:10px;--skin-r-md:14px;--skin-r-lg:19px;--skin-r-xl:26px;\n}\n\n\n:root[data-theme=\"dusk\"],\n[data-theme=\"dusk\"]{\n  /* 暮色 · 偏深暖的琥珀与陶土，傍晚 */\n  --t-canvas:#faf1e8;\n  --t-surface:#fffaf4;\n  --t-surface-soft:#fbf4ec;\n  --t-surface-raised:#ffffff;\n  --t-surface-sunken:#efe0d3;\n  --t-veil:rgba(255,250,244,.74);\n  --t-text:#453831;\n  --t-text-strong:#312721;\n  --t-text-soft:#7a685e;\n  --t-text-faint:#796b64;\n  --t-text-invert:#fffaf4;\n  --t-accent:#b85f42;\n  --t-accent-hover:#9b4b32;\n  --t-accent-quiet:#fae5da;\n  --t-accent-ink:#964b33;\n  --t-accent-solid:#a8553b;\n  --t-accent-solid-hover:#8d452f;\n  --t-on-solid:#fffaf4;\n  --t-line:rgba(120,88,70,.16);\n  --t-line-firm:rgba(120,88,70,.28);\n  --t-ok:#5b7f5c;\n  --t-ok-quiet:#e9f0e5;\n  --t-ok-ink:#4a6a4b;\n  --t-warn:#a8792b;\n  --t-warn-quiet:#f9eed8;\n  --t-warn-ink:#89601d;\n  --t-risk:#ab4f45;\n  --t-risk-quiet:#fae7e4;\n  --t-risk-ink:#8d3f36;\n  --t-focus:#a7553b;\n  --t-shadow:0 8px 28px rgba(110,74,54,.08);\n  --t-shadow-lift:0 14px 36px rgba(110,74,54,.14);\n  --t-brand:#c26c4d;\n  --t-scene-light:dusk;\n  --skin-heading-font:\"Noto Serif SC\",\"Songti SC\",\"SimSun\",serif;\n  --skin-canvas-pattern:repeating-linear-gradient(135deg,transparent 0 11px,color-mix(in srgb,var(--t-accent) 4%,transparent) 11px 12px);\n  --skin-canvas-size:auto;\n  --skin-r-2xs:2px;--skin-r-xs:4px;--skin-r-sm:7px;--skin-r-md:10px;--skin-r-lg:14px;--skin-r-xl:18px;\n}\n\n\n:root[data-theme=\"night\"],\n[data-theme=\"night\"],\n:root[data-theme=\"dark\"],\n[data-theme=\"dark\"]{\n  /* 夜读 · 低照度靛蓝与月白，夜间查看 */\n  --t-canvas:#15171f;\n  --t-surface:#22252f;\n  --t-surface-soft:#1c1f28;\n  --t-surface-raised:#282c38;\n  --t-surface-sunken:#181a22;\n  --t-veil:rgba(28,30,39,.82);\n  --t-text:#e5e6ec;\n  --t-text-strong:#f5f5f9;\n  --t-text-soft:#a5a8b8;\n  --t-text-faint:#878b9a;\n  --t-text-invert:#171920;\n  --t-accent:#93a8d8;\n  --t-accent-hover:#7b92c8;\n  --t-accent-quiet:#252a3a;\n  --t-accent-ink:#b3c3e8;\n  --t-accent-solid:#61749f;\n  --t-accent-solid-hover:#7b92c8;\n  --t-on-solid:#ffffff;\n  --t-line:rgba(255,255,255,.10);\n  --t-line-firm:rgba(255,255,255,.20);\n  --t-ok:#6fbf9a;\n  --t-ok-quiet:#1c3029;\n  --t-ok-ink:#87d0ad;\n  --t-warn:#d9ae6d;\n  --t-warn-quiet:#312818;\n  --t-warn-ink:#e6c287;\n  --t-risk:#d18f98;\n  --t-risk-quiet:#301f23;\n  --t-risk-ink:#dda1aa;\n  --t-focus:#93a8d8;\n  --t-shadow:0 10px 26px rgba(0,0,0,.32);\n  --t-shadow-lift:0 14px 32px rgba(0,0,0,.46);\n  --t-brand:#8b9ed0;\n  --t-scene-light:night;\n  --skin-heading-font:\"Noto Serif SC\",\"Songti SC\",\"SimSun\",serif;\n  --skin-canvas-pattern:repeating-linear-gradient(0deg,transparent 0 35px,color-mix(in srgb,var(--t-accent) 5%,transparent) 35px 36px);\n  --skin-canvas-size:auto;\n  --skin-r-2xs:2px;--skin-r-xs:4px;--skin-r-sm:7px;--skin-r-md:10px;--skin-r-lg:14px;--skin-r-xl:18px;\n}\n\n\n:root[data-theme=\"walnut\"],\n[data-theme=\"walnut\"]{\n  /* 深林 · 胡桃木与苔绿的深色，暖而稳 */\n  --t-canvas:#1d1a16;\n  --t-surface:#2a2620;\n  --t-surface-soft:#242019;\n  --t-surface-raised:#332e26;\n  --t-surface-sunken:#1a1713;\n  --t-veil:rgba(36,32,25,.84);\n  --t-text:#e8e2d6;\n  --t-text-strong:#f5f0e6;\n  --t-text-soft:#b3aa99;\n  --t-text-faint:#948c7d;\n  --t-text-invert:#1a1713;\n  --t-accent:#b5926a;\n  --t-accent-hover:#c8a67f;\n  --t-accent-quiet:#332c22;\n  --t-accent-ink:#d0b28e;\n  --t-accent-solid:#8a6c4a;\n  --t-accent-solid-hover:#a3805a;\n  --t-on-solid:#ffffff;\n  --t-line:rgba(232,226,214,.12);\n  --t-line-firm:rgba(232,226,214,.22);\n  --t-ok:#8aa87a;\n  --t-ok-quiet:#262b1f;\n  --t-ok-ink:#a3bf92;\n  --t-warn:#cfa75f;\n  --t-warn-quiet:#2e2718;\n  --t-warn-ink:#ddba7b;\n  --t-risk:#c98a80;\n  --t-risk-quiet:#2f2220;\n  --t-risk-ink:#d79f96;\n  --t-focus:#b5926a;\n  --t-shadow:0 10px 26px rgba(0,0,0,.34);\n  --t-shadow-lift:0 14px 32px rgba(0,0,0,.48);\n  --t-brand:#aa8a63;\n  --t-scene-light:dusk;\n  --skin-heading-font:\"FangSong\",\"STSong\",\"Songti SC\",serif;\n  --skin-canvas-pattern:repeating-linear-gradient(90deg,transparent 0 79px,color-mix(in srgb,var(--t-accent) 5%,transparent) 79px 80px);\n  --skin-canvas-size:auto;\n  --skin-r-2xs:1px;--skin-r-xs:3px;--skin-r-sm:5px;--skin-r-md:8px;--skin-r-lg:12px;--skin-r-xl:16px;\n}\n\n\n:root[data-theme=\"contrast\"],\n[data-theme=\"contrast\"]{\n  /* 高对比 · 纯黑白加单一高饱和强调，给弱视与强光环境 */\n  --t-canvas:#ffffff;\n  --t-surface:#ffffff;\n  --t-surface-soft:#f4f4f4;\n  --t-surface-raised:#ffffff;\n  --t-surface-sunken:#e8e8e8;\n  --t-veil:rgba(255,255,255,.92);\n  --t-text:#000000;\n  --t-text-strong:#000000;\n  --t-text-soft:#2b2b2b;\n  --t-text-faint:#444444;\n  --t-text-invert:#ffffff;\n  --t-accent:#0033cc;\n  --t-accent-hover:#002599;\n  --t-accent-quiet:#e0e8ff;\n  --t-accent-ink:#002599;\n  --t-accent-solid:#0033cc;\n  --t-accent-solid-hover:#002599;\n  --t-on-solid:#ffffff;\n  --t-line:rgba(0,0,0,.42);\n  --t-line-firm:rgba(0,0,0,.72);\n  --t-ok:#0a6b2f;\n  --t-ok-quiet:#dff5e5;\n  --t-ok-ink:#075423;\n  --t-warn:#8a5a00;\n  --t-warn-quiet:#fdf0d5;\n  --t-warn-ink:#6b4500;\n  --t-risk:#a80016;\n  --t-risk-quiet:#fde5e8;\n  --t-risk-ink:#840012;\n  --t-focus:#0033cc;\n  --t-shadow:0 2px 0 rgba(0,0,0,.28);\n  --t-shadow-lift:0 3px 0 rgba(0,0,0,.42);\n  --t-brand:#0033cc;\n  --t-scene-light:day;\n  --skin-heading-font:\"MiSans\",\"Microsoft YaHei\",\"PingFang SC\",system-ui,sans-serif;\n  --skin-canvas-pattern:none;\n  --skin-canvas-size:auto;\n  --skin-r-2xs:0px;--skin-r-xs:1px;--skin-r-sm:2px;--skin-r-md:3px;--skin-r-lg:4px;--skin-r-xl:6px;\n}\n/* Bundled workspaces project the cottage palette into their existing variables.\n   tools/sync_framework_page.py supplies --t-* from tokens.css without copying\n   layout, dimensions or component rules into the workspace. */\n:root[data-theme] {\n  color-scheme: light;\n  --radius:var(--skin-r-md,12px);\n  --page: var(--t-canvas);\n  --surface: var(--t-surface);\n  --surface-muted: var(--t-surface-soft);\n  --ink: var(--t-text);\n  --muted: var(--t-text-soft);\n  --ink-soft: var(--t-text-faint);\n  --line: var(--t-line);\n  --line-strong: var(--t-line-firm);\n  --accent: var(--t-accent);\n  --accent-strong: var(--t-accent-hover);\n  --accent-soft: var(--t-accent-quiet);\n  --green: var(--t-ok-ink);\n  --green-soft: var(--t-ok-quiet);\n  --success: var(--t-ok-ink);\n  --success-soft: var(--t-ok-quiet);\n  --amber: var(--t-warn-ink);\n  --amber-soft: var(--t-warn-quiet);\n  --warning: var(--t-warn-ink);\n  --warning-soft: var(--t-warn-quiet);\n  --danger: var(--t-risk-ink);\n  --danger-soft: var(--t-risk-quiet);\n  --info: var(--t-accent-ink);\n  --info-soft: var(--t-accent-quiet);\n  --shadow: var(--t-shadow);\n  --shadow-lift: var(--t-shadow-lift);\n  --backdrop: color-mix(in srgb, var(--t-text-strong) 45%, transparent);\n}\n:root[data-theme=\"night\"], :root[data-theme=\"walnut\"] { color-scheme: dark; }\n:root[data-theme] body {\n  background-image:var(--skin-canvas-pattern,none);\n  background-size:var(--skin-canvas-size,auto);\n}\n:root[data-theme] h1,:root[data-theme] h2 {\n  font-family:var(--skin-heading-font,inherit);\n}\n.extension-status-hero{position:relative;display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:var(--sp-3);padding:var(--sp-4);border:1px solid var(--line);border-radius:var(--r-md);background:linear-gradient(135deg,var(--surface),color-mix(in srgb,var(--accent-soft) 55%,var(--surface)));overflow:hidden;animation:extension-rise .45s cubic-bezier(.22,.8,.2,1) both}\n.extension-status-hero::after{position:absolute;inset:0 auto 0 0;width:34%;background:linear-gradient(90deg,color-mix(in srgb,var(--accent) 10%,transparent),transparent);content:\"\";pointer-events:none}\n.extension-status-icon{position:relative;z-index:1;display:grid;width:48px;height:48px;place-items:center;border-radius:var(--r-md);background:var(--accent-soft);color:var(--accent);font-size:var(--fs-display);box-shadow:0 0 0 7px color-mix(in srgb,var(--accent) 7%,transparent)}\n.extension-status-copy{position:relative;z-index:1;min-width:0}.extension-status-copy h3{margin:0;font-size:var(--fs-head)}.extension-status-copy p{margin:var(--sp-1) 0 0;color:var(--muted);font-size:var(--fs-body);line-height:1.55}.extension-status-chip{position:relative;z-index:1;padding:var(--sp-1) var(--sp-2);border:1px solid var(--line-strong);border-radius:var(--r-pill);color:var(--muted);font-size:var(--fs-tiny);white-space:nowrap}.extension-status-hero.ready .extension-status-chip{border-color:color-mix(in srgb,var(--green) 35%,var(--line));background:var(--green-soft);color:var(--green)}.extension-status-hero.warn .extension-status-chip{border-color:color-mix(in srgb,var(--amber) 35%,var(--line));background:var(--amber-soft);color:var(--amber)}\n.extension-flow{display:flex;align-items:center;gap:var(--sp-2);margin:var(--sp-4) 0 var(--sp-5);padding:0 3px}.extension-flow-step{display:grid;grid-template-columns:auto 1fr;column-gap:var(--sp-2);min-width:86px;color:var(--muted);font-size:var(--fs-tiny)}.extension-flow-step b{grid-row:span 2;display:grid;width:23px;height:23px;place-items:center;border-radius:var(--r-xs);background:var(--surface-muted);color:var(--ink-soft);font-size:var(--fs-micro)}.extension-flow-step span{font-weight:700}.extension-flow-step small{font-size:var(--fs-micro);color:var(--ink-soft)}.extension-flow-step.done b{background:var(--accent-soft);color:var(--accent)}.extension-flow-line{flex:1;height:1px;background:linear-gradient(90deg,var(--accent),var(--line-strong));animation:extension-line 1s ease both}\n.extension-live-panel{position:relative;margin:0 0 var(--sp-4);padding:var(--sp-4) var(--sp-4);border:1px solid color-mix(in srgb,var(--accent) 26%,var(--line));border-radius:var(--r-sm);background:var(--accent-soft);overflow:hidden}.extension-live-panel::before{position:absolute;top:0;bottom:0;left:0;width:3px;background:var(--accent);content:\"\"}.extension-live-panel h3{margin:0 0 var(--sp-1);font-size:var(--fs-lead)}.extension-live-panel p{margin:0;color:var(--muted);font-size:var(--fs-body);line-height:1.6}\n.extension-actions{display:flex;align-items:center;justify-content:space-between;gap:var(--sp-3);margin-top:var(--sp-5);padding-top:var(--sp-4);border-top:1px solid var(--line)}.extension-actions strong{font-size:var(--fs-body)}.extension-actions p{margin:var(--sp-1) 0 0;color:var(--muted);font-size:var(--fs-tiny)}.extension-actions .dialog-actions{margin:0}\n@keyframes extension-rise{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}@keyframes extension-line{from{transform:scaleX(0);transform-origin:left}to{transform:scaleX(1)}}\n@media (max-width:620px){.extension-status-hero{grid-template-columns:auto 1fr}.extension-status-chip{grid-column:2;justify-self:start}.extension-flow{gap:var(--sp-1)}.extension-flow-step{min-width:0;flex:1}.extension-flow-line{max-width:18px}.extension-actions{align-items:flex-start;flex-direction:column}.extension-actions .dialog-actions{width:100%;flex-wrap:wrap}}\n@media (prefers-reduced-motion:reduce){.extension-status-hero,.extension-flow-line{animation:none}}\n</style>\n  \n  \n</head>\n<body>\n  <main>\n    <header>\n      <div class=\"host-controls\"><button id=\"start-host\" class=\"secondary\" type=\"button\">启动当前配置</button>\n        <button id=\"stop-host\" class=\"quiet\" type=\"button\">停止运行</button>\n        <button id=\"refresh\" class=\"secondary\" type=\"button\">刷新记录</button></div></header>\n    <section class=\"scope\" aria-label=\"当前范围\">\n      <div><span>角色</span><strong id=\"role\">—</strong></div><div><span>私聊对象</span><strong id=\"participant\">—</strong></div>\n      <div><span>运行状态</span><strong id=\"host-state\">正在连接…</strong></div><div><span>生活日程</span><strong id=\"routine-state\">—</strong></div>\n    </section>\n    <p id=\"next-routines\" class=\"muted schedule-hint\"></p>\n    <section class=\"sleep-plan\" aria-label=\"角色共享作息\">\n      <div><span>自动睡眠范围</span><strong id=\"sleep-scope\">正在读取…</strong></div>\n      <div><span>唯一执行窗口</span><strong id=\"sleep-executor\">—</strong></div>\n      <div><span>下次入睡 / 计划唤醒</span><strong id=\"sleep-next\">—</strong></div>\n      <div><span>当前睡眠唤醒</span><strong id=\"sleep-active-wake\">—</strong></div>\n    </section>\n    <section class=\"sleep-physiology\" aria-label=\"角色睡眠状态\">\n      <div><span>睡眠压力</span><strong id=\"sleep-pressure\">—</strong></div>\n      <div><span>欠睡</span><strong id=\"sleep-debt\">—</strong></div>\n      <div><span>近 24 小时负荷</span><strong id=\"sleep-workload\">—</strong></div>\n      <div><span>推荐睡眠时长</span><strong id=\"sleep-recommended\">—</strong></div>\n    </section>\n    <div id=\"notice\" role=\"status\" aria-live=\"polite\" hidden></div>\n    <details id=\"settings\"><summary>日程与偏好</summary>\n      <form id=\"config-form\">\n        <div class=\"config-grid\">\n          <label class=\"check\"><input id=\"enabled\" type=\"checkbox\">启用生活日程总开关</label>\n          <label>日记时区<input id=\"timezone\" type=\"text\" value=\"Asia/Shanghai\" required></label>\n          <label class=\"check\"><input id=\"diary_enabled\" type=\"checkbox\">每天写日记</label>\n          <label>日记时间<input id=\"diary_time\" type=\"time\" value=\"23:50\" required></label>\n          <label class=\"check\"><input id=\"sleep_enabled\" type=\"checkbox\">按角色作息自动入睡</label>\n          <label>入睡时间<input id=\"sleep_time\" type=\"time\" value=\"00:30\" required></label>\n          <label>入睡时区<input id=\"sleep_timezone\" type=\"text\" value=\"Asia/Shanghai\" required></label>\n          <label>自然浮动上限（分钟）<input id=\"sleep_variation_minutes\" type=\"number\" min=\"0\" max=\"120\" value=\"20\" required>\n            <small class=\"muted\">实际入睡时刻沿近期趋势逐日平缓变化，同一天保持一致。</small></label>\n          <label>入睡观察窗口（分钟）<input id=\"sleep_window_minutes\" type=\"number\" min=\"0\" max=\"360\" value=\"120\" required></label>\n          <label>睡眠时长（分钟）<input id=\"sleep_minutes\" type=\"number\" min=\"1\" max=\"1440\" value=\"480\" required></label>\n          <label class=\"check\"><input id=\"reading_enabled\" type=\"checkbox\">自动阅读书架中的待读片段</label>\n          <label class=\"check\"><input id=\"derive_enabled\" type=\"checkbox\">正文保存后提取摘要与梦境碎片</label>\n        </div>\n        <div class=\"form-footer\"><p class=\"muted\">自动入睡需同时开启生活日程总开关和「按角色作息自动入睡」，并有已授权的私聊执行窗口；角色状态页的睡眠状态模拟是另一项设置。作息按角色共享。</p>\n          <button class=\"primary\" type=\"submit\">保存设置</button></div>\n      </form>\n    </details>\n    <nav class=\"tabs\" aria-label=\"生活记录\">\n      <button type=\"button\" data-tab=\"archive\" aria-current=\"page\">日记与梦境</button>\n      <button type=\"button\" data-tab=\"reading\">阅读书架</button>\n      <button type=\"button\" data-tab=\"sleep\">睡眠记录</button>\n      <button type=\"button\" data-tab=\"receipts\">执行记录</button>\n    </nav>\n    <section id=\"archive\" class=\"tab-panel\">\n      <div class=\"section-head\"><div><h2>私人书写</h2></div>\n        <button id=\"write-diary\" class=\"primary\" type=\"button\">写今天的日记</button></div>\n      <div class=\"archive-layout\"><aside><div id=\"journal-list\" aria-label=\"日记目录\"><p class=\"empty\">正在读取记录…</p></div>\n        <div class=\"pagination\"><button id=\"newer\" class=\"quiet\" type=\"button\" disabled>较新记录</button><button id=\"older\" class=\"quiet\" type=\"button\" disabled>较早记录</button></div></aside>\n        <article id=\"journal-detail\" aria-live=\"polite\"><p class=\"empty\">选择一篇日记或梦境。</p></article></div>\n    </section>\n    <section id=\"reading\" class=\"tab-panel\" hidden>\n      <div class=\"section-head\"><div><h2>阅读书架</h2></div>\n        <button id=\"add-text\" class=\"primary\" type=\"button\">添加原文</button></div>\n      <div id=\"reading-list\" class=\"activity-list\"></div>\n    </section>\n    <section id=\"sleep\" class=\"tab-panel\" hidden>\n      <div class=\"section-head\"><div><h2>睡眠与醒来</h2></div>\n        <button id=\"start-sleep\" class=\"primary\" type=\"button\">开始睡眠</button></div>\n      <div id=\"sleep-list\" class=\"activity-list\"></div>\n    </section>\n    <div id=\"activity-pages\" class=\"pagination\" hidden><button id=\"first-activities\" class=\"quiet\" type=\"button\">回到首批</button><button id=\"more-activities\" class=\"quiet\" type=\"button\">下一批记录</button></div>\n    <section id=\"receipts\" class=\"tab-panel\" hidden>\n      <div class=\"section-head\"><div><h2>执行记录</h2></div></div>\n      <div id=\"receipt-list\" class=\"activity-list\"></div>\n      <form id=\"retry-form\" class=\"retry-form\"><h3>重试已确定失败的书写</h3>\n        <label>失败的书写<select id=\"retry-id\" required><option value=\"\">选择失败的书写</option></select></label>\n        <label>日记日期<input id=\"retry-date\" type=\"date\" required></label>\n        <p class=\"muted\">只可重试已确定失败的日记；梦境请到睡眠记录重试。</p>\n        <button class=\"secondary\" type=\"submit\">重试这天的日记</button>\n      </form>\n    </section>\n  </main>\n  <dialog id=\"editor\" aria-labelledby=\"dialog-title\">\n    <form id=\"editor-form\"><div class=\"section-head\"><h2 id=\"dialog-title\">编辑</h2><button id=\"close-dialog\" class=\"quiet\" type=\"button\" aria-label=\"关闭\">关闭</button></div>\n      <p id=\"dialog-description\" class=\"muted\"></p>\n      <label id=\"title-field\">标题<input id=\"text-title\" maxlength=\"160\"></label>\n      <label id=\"body-field\">正文<textarea id=\"text-body\" rows=\"12\"></textarea></label>\n      <label id=\"glow-field\">醒后余韵<textarea id=\"text-glow\" rows=\"3\"></textarea></label>\n      <label id=\"minutes-field\">睡眠时长（分钟）<input id=\"minutes\" type=\"number\" min=\"1\" max=\"1440\" value=\"480\"></label>\n      <label id=\"retry-field\">书写记录<select id=\"dream-retry\"><option value=\"\">首次记录</option></select></label>\n      <p id=\"dialog-error\" role=\"alert\" hidden></p>\n      <div class=\"dialog-actions\"><button id=\"dialog-submit\" class=\"primary\" type=\"submit\">确认</button></div>\n    </form>\n  </dialog>\n<script>/* Opaque-origin compatible bridge for bundled workspaces. */\n\"use strict\";\n(() => {\n  const pending=new Map();let count=0,context=null,readyResolve;\n  const DEFAULT_REQUEST_TIMEOUT_MS=18000,MAX_REQUEST_TIMEOUT_MS=300000;\n  const ready=new Promise(resolve=>{readyResolve=resolve;});\n  const send=payload=>parent.postMessage({channel:\"companion-workspace\",...payload},\"*\");\n  /* 外观维度：主题沿用原有通道，另外四项按 name/value 应用。\n     工作区各自的样式表只用得上其中一部分，未声明的维度不会产生副作用。\n     主题列表取自 theme.js 注册表，不在这里再抄一份——抄一份就会飘，\n     主页面加主题而工作区不认，值会被这个白名单挡掉、主题静默不生效。 */\n  const themeIds = globalThis.CompanionTheme?.IDS || [\"courtyard\",\"dawn\",\"dusk\",\"night\",\"walnut\",\"contrast\"];\n  const appearanceDimensions={\n    theme:{dataset:\"theme\",values:themeIds},\n    density:{dataset:\"density\",values:[\"compact\",\"standard\",\"roomy\"]},\n    radius:{dataset:\"radius\",values:[\"sharp\",\"standard\",\"round\"]},\n    typeScale:{dataset:\"typeScale\",values:[\"s\",\"m\",\"l\",\"xl\"]},\n    motion:{dataset:\"motion\",values:[\"full\",\"low\",\"off\"]},\n  };\n  const applyDimension=(name,value)=>{\n    const spec=appearanceDimensions[name];\n    // 主题额外走一次旧名迁移：工作区若被单独打开，localStorage 里可能还是 mist/grove/coral。\n    if(name===\"theme\"&&globalThis.CompanionTheme)value=globalThis.CompanionTheme.migrate(value);\n    if(!spec||!spec.values.includes(value))return false;\n    document.documentElement.dataset[spec.dataset]=value;\n    document.dispatchEvent(new CustomEvent(\"companion-appearance-change\",{detail:{name,value}}));\n    return true;\n  };\n  window.addEventListener(\"message\",event=>{\n    if(event.source!==parent||event.data?.channel!==\"companion-workspace\")return;\n    const message=event.data;\n    if(message.kind===\"context\"){context=message.context;readyResolve(context);return;}\n    if(message.kind===\"host-mappings-refreshed\"){\n      document.dispatchEvent(new CustomEvent(\"companion-mappings-change\",{detail:message}));return;\n    }\n    if(message.kind===\"host-mappings-refresh-failed\"){\n      document.dispatchEvent(new CustomEvent(\"companion-mappings-refresh-failed\",{detail:message}));return;\n    }\n    if(message.kind===\"theme\"&&appearanceDimensions.theme.values.includes(message.theme)){\n      applyDimension(\"theme\",message.theme);\n      document.dispatchEvent(new CustomEvent(\"companion-theme-change\",{detail:{theme:message.theme}}));\n      return;\n    }\n    if(message.kind===\"appearance\"){\n      if(message.appearance)for(const [name,value] of Object.entries(message.appearance))applyDimension(name,value);\n      else applyDimension(message.name,message.value);\n      return;\n    }\n    if(message.kind===\"navigate-failed\"){\n      document.dispatchEvent(new CustomEvent(\"companion-navigate-failed\",{detail:message}));return;\n    }\n    if(message.kind!==\"response\"||!pending.has(message.requestId))return;\n    const item=pending.get(message.requestId);pending.delete(message.requestId);clearTimeout(item.timer);\n    if(message.ok)item.resolve(message.data);else item.reject(Object.assign(new Error(message.error),\n      {code:message.code,reason:message.reason,sourceLabel:message.sourceLabel,\n        confirmed:message.confirmed===true}));\n  });\n  function request(method,path,body,options){return new Promise((resolve,reject)=>{\n    const requestId=\"workspace-\"+(++count);\n    const requested=options?.timeoutMs;\n    const timeoutMs=Number.isInteger(requested)&&requested>=1000\n      ?Math.min(requested,MAX_REQUEST_TIMEOUT_MS):DEFAULT_REQUEST_TIMEOUT_MS;\n    const timer=setTimeout(()=>{pending.delete(requestId);reject(Object.assign(\n      new Error(\"未收到执行结果，请核对后重试本次操作。\"),{code:\"bridge_timeout\",confirmed:false}));},timeoutMs+1000);\n    pending.set(requestId,{resolve,reject,timer});send({kind:\"request\",requestId,method,path,body,timeoutMs});\n  });}\n  window.AstrBotPluginPage={ready:()=>ready,getContext:()=>context,\n    apiGet:(path,body,options)=>request(\"GET\",path,body,options),\n    apiPost:(path,body,options)=>request(\"POST\",path,body,options)};\n  document.addEventListener(\"DOMContentLoaded\",async()=>{\n    document.querySelectorAll(\"#start-host,#stop-host\").forEach(el=>el.hidden=true);\n    await ready;\n    if(context.tab)document.querySelector('[data-tab=\"'+CSS.escape(context.tab)+'\"]')?.click();\n    let last=0;\n    new ResizeObserver(()=>{const height=document.body.scrollHeight;if(height!==last){last=height;send({kind:\"resize\",height});}}).observe(document.body);\n  });\n  send({kind:\"ready\"});\n})();\n\n\"use strict\";\n(() => {\n  const $ = id => document.getElementById(id);\n  const node = (tag, text, cls) => { const n = document.createElement(tag); if (text !== undefined) n.textContent = text; if (cls) n.className = cls; return n; };\n  const names = { planned: \"待开始\", active: \"进行中\", paused: \"已暂停\", completed: \"已完成\", complete: \"已完成\", cancelled: \"已取消\", deleted: \"已删除\", absent: \"尚未书写\", written: \"正文已保存\", succeeded: \"成功\", failed: \"失败\", unknown: \"结果未知\", accepted: \"已接纳\", uncertain: \"结果未知\", running: \"运行中\", new: \"尚未启动\", stopped: \"已停止\", draining: \"正在停止\" };\n  const errors = { dashboard_identity_required: \"请从已登录的 AstrBot 管理界面打开本页面。\", staging_not_initialized: \"角色数据尚未就绪，请在「账号与会话」保存角色映射；已保存可重新读取状态。\",\n    host_not_running: \"请先启动当前 V2 配置。\", life_not_bound: \"请先启动当前 V2 配置，以载入原角色。\", authorization_revoked: \"执行权限已关闭或撤销，请确认生活日程设置。\",\n    authorization_missing: \"请先启用生活日程与执行权限。\", life_view_stale: \"记录或权限已经变化，请刷新后重新确认。\", life_reading_unresolved: \"原阅读结果尚未确定，不能重复调用。\",\n    life_reading_active: \"当前片段仍在阅读，请完成或取消后再入睡。\", life_sleeping: \"角色正在睡眠，请先醒来再阅读。\", life_command_invalid: \"生活记录或操作信息已变化，请刷新后重新尝试。\", journal_trigger_unresolved: \"原书写仍在进行、结果未知或已经成功，不能重复执行。\",\n    configuration_revision_conflict: \"设置已变化，请刷新后重新保存。\", core_access_required: \"当前账号没有本体管理权限。\", source_revoked: \"原文已撤回，依赖它的内容已停止使用。\" };\n  let bridge, state, selected, dialogAction, dialogItem, busy = false, dirty = false, tab = \"archive\";\n  let datePages = [null], datePage = 0, activityCursor = null, polling = null;\n  const pending = new Map();\n  const booleanFields = [\"enabled\", \"diary_enabled\", \"sleep_enabled\", \"reading_enabled\", \"derive_enabled\"];\n  const configFields = [...booleanFields, \"timezone\", \"diary_time\", \"sleep_time\", \"sleep_timezone\", \"sleep_variation_minutes\", \"sleep_window_minutes\", \"sleep_minutes\"];\n  const date = value => value ? new Intl.DateTimeFormat(\"zh-CN\", { dateStyle: \"medium\", timeStyle: \"short\" }).format(new Date(value)) : \"—\";\n  const kind = item => item.kind === \"dream\" ? \"梦境\" : \"日记\";\n  const display = () => bridge?.getContext?.()?.display || {};\n  function roleName() {\n    if (display().role_name || state.role_name) return display().role_name || state.role_name;\n    const name = state.role_id;\n    return typeof name === \"string\" && !/^(?:role[-_:]|staging[-_:]|dashboard:)|^[a-f0-9]{24,}$/i.test(name)\n      ? name : \"当前角色\";\n  }\n  function localizedError(value) {\n    const code = value?.code || value?.data?.code || value?.response?.data?.code || value?.message;\n    return Object.assign(new Error(errors[code] || \"操作未完成，请刷新确认记录状态后重试。\"), {code});\n  }\n  function operationKey() {\n    const webCrypto = window.crypto;\n    if (typeof webCrypto?.randomUUID === \"function\") return webCrypto.randomUUID();\n    if (typeof webCrypto?.getRandomValues === \"function\") {\n      return Array.from(webCrypto.getRandomValues(new Uint8Array(16)),\n        value => value.toString(16).padStart(2, \"0\")).join(\"\");\n    }\n    return \"life-\" + Date.now() + \"-\" + Math.random().toString(36).slice(2);\n  }\n  function unwrap(response) {\n    const wrapped = [\"ok\", \"error\"].includes(response?.status) && response?.data !== undefined ? response : [\"ok\", \"error\"].includes(response?.data?.status) && response?.data?.data !== undefined ? response.data : null;\n    if (wrapped?.status === \"error\") throw localizedError(wrapped);\n    // Current AstrBot bridge returns the already-unwrapped data; older bridges return the envelope.\n    const data = wrapped ? wrapped.data : response;\n    if (!data || typeof data !== \"object\") throw new Error(\"未收到执行结果，请刷新确认后重试本次操作。\");\n    return data;\n  }\n  function notice(text, error = false) { $(\"notice\").textContent = text; $(\"notice\").className = error ? \"error\" : \"\"; $(\"notice\").hidden = !text; }\n  function controls(value) {\n    busy = value;\n    document.querySelectorAll(\"button, select\").forEach(b => { b.disabled = value; });\n    $(\"close-dialog\").disabled = false;\n    $(\"newer\").disabled = value || datePage === 0; $(\"older\").disabled = value || !state?.next_date;\n    $(\"more-activities\").disabled = value || !state?.next_activity;\n    $(\"first-activities\").disabled = value || !activityCursor;\n    $(\"start-host\").disabled = value || state?.host_state === \"running\";\n    $(\"stop-host\").disabled = value || !state || [\"new\", \"stopped\"].includes(state.host_state);\n    [\"write-diary\", \"start-sleep\"].forEach(id => { $(id).disabled = value || !state?.config.enabled || state?.host_state !== \"running\"; });\n    /* 配置没读到（state 为 null）时别让用户对着能点的表单白点：整组禁用，\n       具体原因由 load() 的提示给出，刷新成功后自动恢复。 */\n    $(\"config-form\").querySelectorAll(\"input, button\").forEach(el => { el.disabled = value || !state; });\n  }\n  async function api(method, body) {\n    try {\n      const response = method === \"GET\" ? await bridge.apiGet(\"life\", body) : await bridge.apiPost(\"life/command\", body);\n      return unwrap(response);\n    } catch (error) { throw localizedError(error); }\n  }\n  async function send(action, args = {}, item = null) {\n    if (busy || !state) return;\n    const body = { action, view_token: item?.view_token || state.view_token, ...args };\n    if (item) {\n      body.expected_revision = item.revision;\n      if (item.activity_id) body.activity_id = item.activity_id;\n      else { body.kind = item.kind; body.local_date = item.local_date; }\n    }\n    const signature = JSON.stringify(body);\n    if (!pending.has(signature)) pending.set(signature, { ...body, operation_key: operationKey() });\n    controls(true); $(\"dialog-error\").hidden = true;\n    notice([\"diary\", \"dream\", \"derive\"].includes(action) ? \"正在书写…\" : \"正在保存…\");\n    try {\n      const result = await api(\"POST\", pending.get(signature));\n      pending.delete(signature);\n      if (action === \"configure\") dirty = false;\n      $(\"editor\").close();\n      notice(result.state === \"failed\" || result.state === \"unknown\" ? \"本次书写未完成，详情已保留在执行记录。\" : \"操作已完成。\", [\"failed\", \"unknown\"].includes(result.state));\n      await load(true);\n    } catch (error) {\n      notice(error.message, true);\n      if ($(\"editor\").open) { $(\"dialog-error\").textContent = error.message; $(\"dialog-error\").hidden = false; }\n    } finally { controls(false); }\n  }\n  function actionButton(label, action, item, direct = false) {\n    const b = node(\"button\", label, [\"delete\", \"cancel\", \"withdraw\"].includes(action) ? \"danger\" : \"secondary\");\n    b.type = \"button\"; b.addEventListener(\"click\", () => direct ? send(action, {}, item) : open(action, item)); return b;\n  }\n  function renderArchive() {\n    const list = $(\"journal-list\"); list.replaceChildren();\n    if (!state.journals.length) list.append(node(\"p\", \"这里还没有日记或梦境。\", \"empty\"));\n    selected = state.journals.find(j => j.kind === selected?.kind && j.local_date === selected?.local_date) || state.journals[0] || null;\n    for (const item of state.journals) {\n      const b = node(\"button\", `${item.local_date} · ${kind(item)}`, \"journal-link\"); b.type = \"button\";\n      b.setAttribute(\"aria-current\", String(item === selected));\n      b.append(node(\"small\", item.state === \"deleted\" ? \"已删除\" : item.unavailable_reason ? \"来源不可用\" : (item.body || item.afterglow || \"\").slice(0, 45)));\n      b.addEventListener(\"click\", () => { selected = item; renderArchive(); }); list.append(b);\n    }\n    const detail = $(\"journal-detail\"); detail.replaceChildren();\n    if (!selected) { detail.append(node(\"p\", \"选择一篇日记或梦境。\", \"empty\")); return; }\n    const item = selected;\n    detail.append(node(\"p\", item.local_date, \"eyebrow\"), node(\"h2\", kind(item)));\n    if (item.state === \"deleted\") detail.append(node(\"p\", \"这篇记录已删除。可以主动填写正文后恢复。\", \"prose\"));\n    else if (item.unavailable_reason) detail.append(node(\"p\", \"依赖的原来源已不可用，正文与摘要已隐藏。\", \"prose\"));\n    else {\n      detail.append(node(\"p\", item.body, \"prose\"));\n      if (item.afterglow) detail.append(node(\"p\", item.afterglow, \"afterglow\"));\n      if (item.summary) { const summary = node(\"div\", undefined, \"journal-summary\"); summary.append(node(\"h3\", \"书写索引\"), node(\"p\", item.summary)); detail.append(summary); }\n      if (item.dream_fragments?.length) { const ul = node(\"ul\"); item.dream_fragments.forEach(s => ul.append(node(\"li\", s))); detail.append(ul); }\n    }\n    const actions = node(\"div\", undefined, \"actions\");\n    if (item.state === \"deleted\") actions.append(actionButton(\"填写正文并恢复\", \"restore\", item));\n    else { if (!item.unavailable_reason) actions.append(actionButton(\"更正正文\", \"edit\", item), actionButton(\"提取索引\", \"derive\", item, true)); actions.append(actionButton(\"删除\", \"delete\", item)); }\n    detail.append(actions);\n  }\n  function renderActivities() {\n    for (const type of [\"reading\", \"sleep\"]) {\n      const list = $(type + \"-list\"); list.replaceChildren();\n      const items = state.activities.filter(a => a.kind === type);\n      if (!items.length) list.append(node(\"p\", type === \"reading\" ? \"本批暂无阅读片段。\" : \"本批没有睡眠记录。\", \"empty\"));\n      for (const item of items) {\n        const card = node(\"article\", undefined, \"activity\");\n        card.append(node(\"h3\", item.title), node(\"span\", names[item.state] || \"状态待核对\", \"badge\"));\n        card.append(node(\"p\", `${date(item.started_at)}${item.due_at ? \" · 计划醒来 \" + date(item.due_at) : \"\"}`, \"muted\"));\n        if (item.unavailable_reason) card.append(node(\"p\", \"原文已不可用，停止后续阅读并隐藏读后感。\", \"prose\"));\n        else if (item.reflection) card.append(node(\"p\", item.reflection, \"prose\"));\n        if (item.task && item.task.state !== \"succeeded\") card.append(node(\"p\", \"阅读执行：\" + (names[item.task.state] || \"状态待核对\"), \"muted\"));\n        const actions = node(\"div\", undefined, \"actions\");\n        if (type === \"reading\" && [\"planned\", \"paused\"].includes(item.state) && !item.unavailable_reason && item.task?.state !== \"unknown\") actions.append(actionButton(item.state === \"paused\" ? \"重新阅读\" : \"开始阅读\", \"read\", item, true));\n        if (type === \"sleep\" && item.state === \"active\") actions.append(actionButton(\"现在醒来\", \"wake\", item));\n        if (type === \"sleep\" && item.state === \"completed\") actions.append(actionButton(\"记录 / 重试梦境\", \"dream\", item));\n        if ([\"planned\", \"active\", \"paused\"].includes(item.state)) actions.append(actionButton(\"取消\", \"cancel\", item));\n        if (type === \"reading\" && !item.unavailable_reason) actions.append(actionButton(\"撤回原文\", \"withdraw\", item));\n        card.append(actions); list.append(card);\n      }\n    }\n  }\n  function renderReceipts() {\n    const list = $(\"receipt-list\"); list.replaceChildren();\n    const receipts = [...new Map(state.receipts.map(r => [r.operation_id || r.key, r])).values()].reverse();\n    if (!receipts.length) list.append(node(\"p\", \"暂无书写执行记录。\", \"empty\"));\n    receipts.forEach((item, index) => {\n      const card = node(\"article\", undefined, \"activity\");\n      card.append(node(\"strong\", `书写记录 ${index + 1} · ${names[item.state] || \"状态待核对\"}`));\n      if (item.code) card.append(node(\"p\", errors[item.code] || \"本次书写未完成，请核对模型与执行权限后重试。\", \"muted\"));\n      list.append(card);\n    });\n    const failed = receipts.map((item, index) => ({item, index})).filter(({item}) => item.state === \"failed\" && item.operation_id);\n    for (const id of [\"retry-id\", \"dream-retry\"]) {\n      const select = $(id), previous = select.value;\n      select.replaceChildren(new Option(id === \"dream-retry\" ? \"首次记录\" : failed.length ? \"选择失败的书写\" : \"暂无已确定失败的书写\", \"\"),\n        ...failed.map(({item, index}) => new Option(`书写记录 ${index + 1} · 失败`, item.operation_id || item.key)));\n      select.value = failed.some(({item}) => (item.operation_id || item.key) === previous) ? previous : \"\";\n    }\n    $(\"retry-form\").hidden = failed.length === 0;\n  }\n  function renderSleepPlan() {\n    const plan = state.sleep_schedule;\n    if (!plan) {\n      $(\"sleep-scope\").textContent = \"暂不可用\"; $(\"sleep-executor\").textContent = \"—\";\n      $(\"sleep-next\").textContent = \"—\"; $(\"sleep-active-wake\").textContent = \"—\";\n      $(\"sleep-pressure\").textContent = \"—\"; $(\"sleep-debt\").textContent = \"—\";\n      $(\"sleep-workload\").textContent = \"—\"; $(\"sleep-recommended\").textContent = \"—\"; return;\n    }\n    $(\"sleep-scope\").textContent = plan.enabled ? \"当前角色 · 各会话共享\" : \"未启用\";\n    const executorName = plan.executor_is_current ? \"当前私聊窗口\" : \"同一角色的其他私聊窗口\";\n    $(\"sleep-executor\").textContent = !plan.enabled ? \"未安排\"\n      : plan.executor_state !== \"available\" ? \"暂无有效授权窗口\"\n        : `${executorName}${plan.executor_is_current ? \"（本页）\" : \"\"}`;\n    $(\"sleep-next\").textContent = plan.next_sleep_at\n      ? `${date(plan.next_sleep_at)} · ${date(plan.next_wake_at)}` : \"未安排\";\n    $(\"sleep-active-wake\").textContent = plan.active_wake_at ? date(plan.active_wake_at) : \"当前没有进行中的睡眠\";\n    const profile = plan.physiology || {};\n    $(\"sleep-pressure\").textContent = profile.sleep_pressure == null ? \"暂无记录\" : `${profile.sleep_pressure} / 100`;\n    $(\"sleep-debt\").textContent = profile.has_sleep_history ? `${Math.round(profile.sleep_debt_minutes || 0)} 分钟` : \"暂无记录\";\n    $(\"sleep-workload\").textContent = `${Math.round(profile.workload_score || 0)} / 100`;\n    $(\"sleep-recommended\").textContent = plan.recommended_duration_minutes\n      ? `${Math.round(plan.recommended_duration_minutes / 60 * 10) / 10} 小时` : \"—\";\n  }\n  function render() {\n    $(\"role\").textContent = roleName();\n    $(\"participant\").textContent = display().subject_name || \"当前聊天对象\";\n    $(\"host-state\").textContent = names[state.host_state] || \"状态待核对\";\n    $(\"routine-state\").textContent = state.config.enabled ? \"已启用\" : \"未启用\";\n    $(\"next-routines\").textContent = [state.next_diary_at ? \"下次日记：\" + date(state.next_diary_at) : \"\", state.next_sleep_at ? \"下次入睡：\" + date(state.next_sleep_at) : \"\"].filter(Boolean).join(\" · \");\n    renderSleepPlan();\n    if (!dirty) configFields.forEach(k => { if (booleanFields.includes(k)) $(k).checked = state.config[k]; else $(k).value = state.config[k]; });\n    renderArchive(); renderActivities(); renderReceipts(); controls(busy);\n    if (state.failure_code) notice(errors[state.failure_code] || \"生活日程已暂停，请检查执行权限与设置。\", true);\n  }\n  async function load(preserveNotice = false) {\n    if (!bridge) return;\n    try {\n      state = await api(\"GET\", { ...(datePages[datePage] ? { before: datePages[datePage] } : {}), ...(activityCursor ? { after_activity: activityCursor } : {}) });\n      if (!preserveNotice) notice(\"\"); render();\n      clearTimeout(polling);\n      if (state.running.length || state.activities.some(a => a.state === \"active\") || state.config.reading_enabled) polling = setTimeout(() => { if (!busy && !document.hidden) load(true); }, 3000);\n    } catch (error) {\n      state = selected = null;\n      [\"journal-list\", \"journal-detail\", \"reading-list\", \"sleep-list\", \"receipt-list\", \"retry-id\", \"dream-retry\"].forEach(id => $(id).replaceChildren());\n      $(\"retry-form\").hidden = true;\n      for (const id of [\"role\", \"participant\", \"sleep-scope\", \"sleep-executor\", \"sleep-next\", \"sleep-active-wake\", \"sleep-pressure\", \"sleep-debt\", \"sleep-workload\", \"sleep-recommended\"]) $(id).textContent = \"—\";\n      /* 配置/状态没读到时给出明确状态，而不是一排“—”：用户能分清是\n         「没有配置」还是「这次没读到」，也知道下一步点哪里。 */\n      $(\"routine-state\").textContent = \"读取失败\";\n      $(\"host-state\").textContent = \"暂不可用\";\n      $(\"settings\").open = true;\n      $(\"editor\").close();\n      notice(`${error.message} 配置暂时无法读取或保存，请点「刷新记录」重试。`, true);\n      controls(false);\n    }\n  }\n  function open(action, item = null) {\n    dialogAction = action; dialogItem = item;\n    const titles = { add_text: \"添加阅读原文\", sleep: \"开始睡眠\", edit: \"更正正文\", restore: \"主动恢复正文\", delete: \"删除这篇书写\", cancel: \"取消活动\", withdraw: \"撤回阅读原文\", wake: \"结束这段睡眠\", dream: \"记录或重试梦境\" };\n    $(\"dialog-title\").textContent = titles[action];\n    $(\"dialog-description\").textContent = { withdraw: \"整份原文及其所有片段将停止使用，依赖它的私人书写也将隐藏。\", delete: \"删除后自动书写不会覆盖此记录，恢复需要主动填写正文。\", wake: \"确认醒来后，会独立记录这段睡眠的梦境。\", add_text: \"保存完整原文，较长资料会拆为连续阅读片段。收存不会标记已读。\" }[action] || \"确认当前记录后保存。\";\n    $(\"title-field\").hidden = action !== \"add_text\";\n    $(\"body-field\").hidden = ![\"add_text\", \"edit\", \"restore\"].includes(action);\n    $(\"glow-field\").hidden = ![\"edit\", \"restore\"].includes(action) || item?.kind !== \"dream\";\n    $(\"minutes-field\").hidden = action !== \"sleep\"; $(\"retry-field\").hidden = action !== \"dream\";\n    $(\"text-title\").value = \"\"; $(\"text-body\").value = item?.body || \"\"; $(\"text-glow\").value = item?.afterglow || \"\"; $(\"dream-retry\").value = \"\";\n    $(\"text-title\").required = action === \"add_text\"; $(\"text-body\").required = action === \"add_text\" || ([\"edit\", \"restore\"].includes(action) && item?.kind !== \"dream\");\n    $(\"minutes\").value = state.config.sleep_minutes; $(\"dialog-error\").hidden = true;\n    $(\"editor\").showModal();\n  }\n  document.querySelectorAll(\"[data-tab]\").forEach(b => b.addEventListener(\"click\", () => {\n    tab = b.dataset.tab; document.querySelectorAll(\"[data-tab]\").forEach(x => x.setAttribute(\"aria-current\", x === b ? \"page\" : \"false\"));\n    document.querySelectorAll(\".tab-panel\").forEach(p => { p.hidden = p.id !== tab; }); $(\"activity-pages\").hidden = ![\"reading\", \"sleep\"].includes(tab);\n  }));\n  $(\"config-form\").addEventListener(\"input\", () => { dirty = true; });\n  $(\"config-form\").addEventListener(\"submit\", e => {\n    e.preventDefault();\n    /* 状态没读到时 state 仍是 null：这里以前会直接读 state.edit_token 抛错，\n       表单看起来“点了没反应”。先把原因说清楚，再让用户刷新。 */\n    if (!state) { $(\"settings\").open = true; notice(\"配置尚未读取成功，请先点「刷新记录」重试后再保存。\", true); return; }\n    try {\n      const changes = {};\n      configFields.forEach(k => { changes[k] = booleanFields.includes(k) ? $(k).checked : [\"sleep_minutes\", \"sleep_variation_minutes\", \"sleep_window_minutes\"].includes(k) ? Number($(k).value) : $(k).value; });\n      send(\"configure\", { changes, edit_token: state.edit_token });\n    } catch (error) { notice(error?.message || \"保存失败，请刷新后重试。\", true); }\n  });\n  $(\"editor-form\").addEventListener(\"submit\", e => {\n    e.preventDefault(); const args = {};\n    if (dialogAction === \"add_text\") { args.title = $(\"text-title\").value; args.text = $(\"text-body\").value; }\n    if ([\"edit\", \"restore\"].includes(dialogAction)) { args.body = $(\"text-body\").value; args.afterglow = dialogItem.kind === \"dream\" ? $(\"text-glow\").value : \"\"; }\n    if (dialogAction === \"sleep\") args.minutes = Number($(\"minutes\").value);\n    if (dialogAction === \"dream\" && $(\"dream-retry\").value.trim()) args.retry_of = $(\"dream-retry\").value.trim();\n    send(dialogAction, args, dialogItem);\n  });\n  $(\"retry-form\").addEventListener(\"submit\", e => { e.preventDefault(); send(\"diary\", { local_date: $(\"retry-date\").value, retry_of: $(\"retry-id\").value.trim() }); });\n  $(\"close-dialog\").addEventListener(\"click\", () => $(\"editor\").close());\n  $(\"refresh\").addEventListener(\"click\", () => load());\n  async function hostControl(action) {\n    if (busy || !bridge) return;\n    controls(true); notice(action === \"start\" ? \"正在载入当前角色并启动…\" : \"正在停止运行…\");\n    const call = async name => unwrap(await bridge.apiPost(\"staging/\" + name, {}));\n    try {\n      if (action === \"start\") {\n        const status = unwrap(await bridge.apiGet(\"staging/status\", {}));\n        if (!status.runtime_open) { await call(\"probe\"); await call(\"initialize\"); }\n      }\n      await call(action); await load();\n    } catch (error) { notice(localizedError(error).message, true); } finally { controls(false); }\n  }\n  $(\"start-host\").addEventListener(\"click\", () => hostControl(\"start\"));\n  $(\"stop-host\").addEventListener(\"click\", () => hostControl(\"stop\"));\n  $(\"add-text\").addEventListener(\"click\", () => { if (state) open(\"add_text\"); });\n  $(\"start-sleep\").addEventListener(\"click\", () => open(\"sleep\"));\n  $(\"write-diary\").addEventListener(\"click\", () => send(\"diary\"));\n  $(\"older\").addEventListener(\"click\", () => { datePages[++datePage] = state.next_date; load(); });\n  $(\"newer\").addEventListener(\"click\", () => { datePage--; load(); });\n  $(\"more-activities\").addEventListener(\"click\", () => { activityCursor = state.next_activity; load(); });\n  $(\"first-activities\").addEventListener(\"click\", () => { activityCursor = null; load(); });\n  document.addEventListener(\"visibilitychange\", () => { if (!document.hidden && !busy) load(true); });\n  document.addEventListener(\"companion-mappings-change\", () => { if (bridge && !busy) void load(true); });\n  (async () => { try { await window.AstrBotPluginPage.ready(); bridge = window.AstrBotPluginPage; await load(); } catch (_) { notice(\"无法连接管理界面，请从 AstrBot 插件页面重新打开。\", true); } })();\n})();\n</script></body>\n</html>\n";
